import {guideImage} from './guide-image.js';
import {printGuide} from './print-guide.js';
import {receivePrivatePreview} from './private-preview.js';
sessionStorage.removeItem('pathira-preview');
import {loginURL} from './navigation.js';
import {supabase} from './cloud.js';
import {rpc} from './repository.js';
import {escapeHTML as esc,safeImage,safeURL,interpolate,uid} from './domain.js';
const root=document.querySelector('#viewer'),params=new URLSearchParams(location.search),token=params.get('share'),sid=uid();let doc,position=0,password='',tracking=false;
function track(kind){if(token&&tracking)rpc('record_event',{t:token,passphrase:password,sid,event_kind:kind,step:kind==='step'?doc.steps[position].id:''}).catch(()=>{})}
function render(){const s=doc.steps[position];document.title=doc.title+' — Pathira';root.innerHTML=`<header><a href="workspace.html">${esc(doc.branding?.name||'Pathira')}</a><h1>${esc(doc.title)}</h1><p>${doc.steps.length?position+1:0} of ${doc.steps.length}</p></header>${s?`<article class="step-card"><div class="step-content"><h2 tabindex="-1">${esc(interpolate(s.title,doc.variables||{}))}</h2>${guideImage(s)}<p style="white-space:pre-wrap">${esc(interpolate(s.description,doc.variables||{}))}</p>${safeURL(s.url)?`<a href="${esc(safeURL(s.url))}" target="_blank" rel="noopener noreferrer">Open source page</a>`:''}${['audio','video'].map(k=>new RegExp('^data:'+k+'/[\\w.+-]+;base64,[A-Za-z0-9+/=\\s]+$').test(s[k]||'')?`<${k} controls style="max-width:100%" src="${s[k]}"></${k}>`:'').join('')}<div class="toolbar">${(s.branches||[]).filter(b=>doc.steps.some(x=>x.id===b.target)).map((b,i)=>`<button data-branch="${esc(b.target)}">${esc(b.label)}</button>`).join('')}</div></div></article>`:'<p>This guide has no steps yet.</p>'}<div class="toolbar"><button id="previous" ${position===0?'disabled':''}>Previous</button><button id="next">${position>=doc.steps.length-1?'Finish':'Next step'}</button><button id="print">Print / save PDF</button></div>${token?'<label><input id="tracking" type="checkbox"> Share anonymous progress for this visit</label><details><summary>Comment or report outdated instructions</summary><textarea id="feedback" maxlength="2000" aria-label="Your feedback"></textarea><select id="kind"><option value="comment">Comment</option><option value="outdated">Outdated instructions</option></select><button id="send-feedback">Send feedback</button><p>Sign in to submit feedback. Your identity is visible to the workspace.</p></details>':''}<p id="notice" role="status"></p>`;document.querySelector('#previous').onclick=()=>go(position-1);document.querySelector('#next').onclick=()=>{if(position<doc.steps.length-1)go(position+1);else{track('complete');document.querySelector('#notice').textContent='Guide completed. You can revisit any step.'}};document.querySelector('#print').onclick=()=>printGuide(doc).catch(e=>{document.querySelector('#notice').textContent=e.message});document.querySelectorAll('[data-branch]').forEach(b=>b.onclick=()=>go(doc.steps.findIndex(s=>s.id===b.dataset.branch)));if(token){const t=document.querySelector('#tracking');t.checked=tracking;t.onchange=()=>{tracking=t.checked;if(tracking){track('view');track('step')}};document.querySelector('#send-feedback').onclick=async()=>{try{await rpc('comment_guide',{t:token,passphrase:password,message:document.querySelector('#feedback').value,step:s?.id||'',report_kind:document.querySelector('#kind').value});document.querySelector('#notice').textContent='Feedback sent.'}catch(e){document.querySelector('#notice').textContent=e.message}}}}
function go(n){position=n;render();root.querySelector('h2')?.focus();track('step')}
async function load(){try{doc=params.has('preview')?await receivePrivatePreview(params.get('preview')):await rpc('shared_document',{t:token,passphrase:password});if(!doc||!Array.isArray(doc.steps))throw Error('Guide unavailable');render()}catch(e){if(params.has('preview')){root.innerHTML=`<h1>Private preview unavailable</h1><p role="alert">${esc(e.message)}</p><a href="index.html">Return to workspace</a>`;return;}root.innerHTML=`<h1>Open shared guide</h1><p role="alert">${esc(e.message)}</p><form><label>Guide password<input type="password" autocomplete="current-password"></label><button>Open guide</button></form><p><a href="${esc(loginURL(location))}">Sign in for domain-restricted guides</a>, then return to this link.</p>`;root.querySelector('form').onsubmit=e=>{e.preventDefault();password=root.querySelector('input').value;load()}}}
load();
